def compute(vars):
    shares_attested = vars["v1"]
    total_shares_purchased = vars["v2"]
    if total_shares_purchased == 0:
        return None
    ratio = shares_attested / total_shares_purchased
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "shares_attested": shares_attested,
            "total_shares_purchased": total_shares_purchased,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
